    duringReading: ['الاستماع الأول: بماذا أقرّت الملائكة؟ ومن أين جاء كبر إبليس؟', 'ضع خطًّا تحت جملة نفي العبادة وتحت جملة «وإنما كان سجودهم...».', 'ارسم خريطة حجة إبليس: الادعاء / المعيار / الدليل المضاد من النص.', 'ضع دائرة حول «وهو» و«أي» (توضيح) ومربعًا حول «لأنّ» و«بسبب» (تعليل).'],
    afterReading: ['أنجز التحدي السريع (اختيار من متعدد) وبرّر بالدليل المضاد.', 'التركيز اللغوي: فرز التوضيح والتعليل في النشاط 1، ثم ضبط «أنّ/لكنّ/يكن» في النشاط 2، ثم الحصر والمصدر في النشاط 3.', 'اكتب أو قل فقرة تناقش معيارًا ضعيفًا في مثال يومي.'],
    lessonPlan: '0–5 بطاقة «مَن يجلس في الصف الأول هو أفضل طالب»: كل ثنائي يكتب سببًا يجعل المعيار غير كافٍ؛ 5–11 استماع ثم قراءة صامتة، وتحديد جملة نفي العبادة وجملة «وإنما»؛ 11–18 خريطة حجة إبليس في ثنائيات (ادعاء / معيار / دليل مضاد)، ثم قراءة جهرية مضبوطة لجملة «ولكنّ أصلَ آدم عليه السلام المتواضع يدل على...»؛ 18–22 التحدي السريع؛ 22–32 التركيز اللغوي: النشاط 1 اكتشافًا جماعيًّا (هل تشرح أم تعلّل؟)، والنشاطان 2–3 في ثنائيات مع كتابة سبب كل اختيار؛ 32–38 استعمال: فقرة النشاط 4 عن معيار ضعيف (مثل الحكم على شخص بملابسه أو لهجته)، شفهيًّا في ثنائيات ثم كتابة أربع جمل؛ 38–40 بطاقة الخروج',
    discussionPoints: ['ما الدليل الذي يستعمله الفصل ضد معيار إبليس؟', 'لماذا يحرص الكاتب على أن يوضح «الأصل» بـ«أي العرق أو اللون أو الانتماء العرقي»؟', 'ما الذي يميّز علم آدم عن علم الملائكة بحسب الفصل؟'],
    interactiveTips: ['افتح نقطة «العلم والطاعة» بعد تحديد جملة «وإنما كان سجودهم طاعة لله».', 'استخدم نقطة «التفوق الزائف» لتلخيص خلل المعيار قبل النشاط 4.', 'لا تقبل أمثلة تقارن بين أصول الطلاب أو ألوانهم، واقترح أمثلة محايدة (الملابس، الهاتف، الشهرة).'],
    differentiation: { strugglingLearners: 'إطار من أربع جمل: «يدّعي ____ أنّ ____ أفضل، أي ____. ويعتمد على هذا المعيار لأنّ ____. ومن جهة أخرى، ____. ولكنّ ____ يدلّ على أنّ ____.»', fastFinishers: 'حلّل معيارين ضعيفين من الحياة المدرسية، واكتب لكل منهما دليلًا مضادًّا وجملة حصر بـ«إنما».' },
    formativeAssessment: ['يشرح السجود طاعةً واحترامًا بدليل النص.', 'يحدّد معيار إبليس والدليل المضاد.', 'يميّز أدوات التوضيح من أدوات التعليل.', 'يضبط اسم «أنّ/لكنّ» وخبر «يكن».'],
    expectedResponses: ['لم يكن سجود الملائكة عبادة لأن السجود للعبادة لا يكون إلا لله، وإنما كان طاعة لله واحترامًا لآدم لأن علمه الفريد يختلف عن علم الملائكة. أما إبليس فبنى كبره على أصل المادة، ولكنّ أصل آدم المتواضع يدل على أن الله لا يركز على العرق أو اللون، لأن جميع البشر يرجعون إلى طين يابس.'],
